                    target = (ROOT / unquote(url.path.lstrip('/'))).resolve() if url.path else ROOT / name
                    self.assertTrue(target.is_relative_to(ROOT), f'{name}: escaping link {link}')
                    if target.is_dir():
                        target /= 'index.html'
